import 'dart:convert';

import 'package:flutter/services.dart';
import 'package:material_ui/material_ui.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'app_design.dart';
import 'phone_preview.dart';

/// Generated by KAkAo. The whole app is driven by assets/design.json.
/// Build the owner's Admin app with:  flutter build apk --dart-define=ADMIN=true
/// (adds the Admin Panel to add/edit products; saved on the device).
const isAdminBuild = bool.fromEnvironment('ADMIN');

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final prefs = await SharedPreferences.getInstance();
  final saved = prefs.getString('design');
  final json = jsonDecode(saved ?? await rootBundle.loadString('assets/design.json')) as Map<String, dynamic>;
  runApp(GeneratedApp(design: AppDesign.fromJson(json), prefs: prefs));
}

class GeneratedApp extends StatefulWidget {
  final AppDesign design;
  final SharedPreferences prefs;
  const GeneratedApp({super.key, required this.design, required this.prefs});

  @override
  State<GeneratedApp> createState() => _GeneratedAppState();
}

class _GeneratedAppState extends State<GeneratedApp> {
  late AppDesign design = widget.design;

  void _save(AppDesign d) {
    setState(() => design = d);
    widget.prefs.setString('design', jsonEncode(d.toJson()));
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: design.name,
      debugShowCheckedModeBanner: false,
      home: LivePreviewApp(design: design, onChanged: isAdminBuild ? _save : null),
    );
  }
}
